\end{definition}


\begin{lemma}\label{lem:L2Martingales.norm_eq_zero}
  \uses{def:L2Martingales.norm}
For $M \in \mathcal{M}^2(E)$, $\Vert M \Vert = 0$ if and only if $M = 0$.
